n("ג'ולי", "ג'ולי היא צורה צרפתית ואנגלית של יוליה, הצורה של השם הרומי יוליוס בלשון נקבה. יוליוס היה שם של משפחה רומית עתיקה. מאותו שם באים גם השמות ג'וליה וג'וליא, ובכל שפה הוא נשמע מעט אחרת.", ["ג'וליה", "ג'וליא"])
n("גב", "גב הוא החלק האחורי של הגוף, ובעברית העתיקה המילה משמשת גם למקום גבוה, גבעה או תל. מאותו שורש באות גם המילים גבוה וגובה. על שם המקום נקרא הקיבוץ עין גב, על החוף המזרחי של הכנרת, למרגלות הגולן.")
n("גיטה", "גיטה היא צורה של גיטל, שם יידי שבא מהמילה גוט, טוב, ופירושו טובה. בקהילות אשכנז נבנו לשם הזה כמה צורות, כמו גיטל, גיטה וגיטי, וכולן נשמעות קרוב. ביידיש השם גיטל הוא תרגום של השם העברי טובה.", ["גיטל", "גיטי"])
n("היא-לי", "היא־לי מחבר שתי מילים קצרות, היא ולי, ופירושו היא שלי. השם נבנה בעברית החדשה, כמו שמות נוספים שמחברים את המילה לי עם מילה אחרת, כמו ליהוא וליה. המקף מפריד בין שני החלקים ומראה איך השם נבנה.")
n("וחיד", "וחיד בא מהשורש הערבי ו־ח־ד, שעניינו אחדות, ופירושו יחיד ומיוחד, מי שאין עוד כמותו. השורש הערבי קרוב למילה העברית אחד, ושתיהן באות ממקור שמי משותף. בערבית של היום המילה ואחד היא המספר אחד.")
n("ויקטוריה", "ויקטוריה היא המילה הלטינית לניצחון, והיא באה מהפועל הלטיני לנצח. מאותה מילה לטינית באה גם המילה האנגלית לניצחון. השם נפוץ בשפות רבות של אירופה, וגם בשמות של מקומות בעולם, ובכל שפה הוא נשמע מעט אחרת.")
n("זהרה", "זהרה היא המילה הערבית לפרח, ובעיקר לפרח שנפתח בעץ או בשיח. השורש הערבי ז־ה־ר עניינו גם זוהר ובוהק, כמו פרח שמאיר בצבעים שלו. בערבית של היום המילה משמשת גם בהשאלה לדבר יפה וצעיר, בתחילת הפריחה שלו.")
n("חאפז", "חאפז בא מהשורש הערבי ח־פ־ט׳, שעניינו שמירה, ופירושו מי ששומר ומגן. בערבית המילה משמשת גם למי שזוכר טקסט ארוך בעל פה, ששומר אותו בזיכרון. השם מתאר מי שאפשר לסמוך עליו שישמור על מה שהופקד בידיו.")
n("חלמי", "חלמי בנוי על המילה הערבית חלם, סבלנות ומתינות, עם הסיומת ־י, שהופכת אותה לתואר, ופירושו מי שסבלני ומתון. מאותו שורש בא בערבית גם השם חלים. אין קשר בין השם לבין המילה העברית חלום, אף שהן נשמעות דומה.")
n("חמדאללה", "חמדאללה מחבר את המילה הערבית חמד, שבח והודיה, עם אללה, אלוהים, ופירושו תודה לאל. זה צירוף שגור מאוד בערבית, ואומרים אותו בשיחה של יום יום, כמו שאומרים בעברית תודה לאל או ברוך השם. מאותו שורש, ח־מ־ד, באים גם השמות חאמד וחמדאן.")
n("טאהר", "טאהר בא מהשורש הערבי ט־ה־ר, שעניינו ניקיון, ופירושו טהור, נקי ותם. השורש משותף לערבית ולעברית, וממנו באות בעברית המילים טהור, טוהר וטהרה. השם מתאר מי שאין בו כוונה רעה.")
n("טופז", "טופז הוא אבן חן שקופה, ולרוב בגוון צהוב או זהוב, אבל יש ממנה גם אבנים כחולות ובצבעים נוספים. המילה באה מהיוונית, ועברה ממנה לשפות רבות. כמו שמות נוספים של אבני חן, השם נבנה על דבר נוצץ ויקר.")
n("כמיל", "כמיל בא מהשורש הערבי כ־מ־ל, שעניינו השלמה, ופירושו מושלם ושלם, דבר שאין בו חסר. מאותו שורש באים בערבית גם השם כמאל, שלמות, ומילים שמתארות סוף טוב של עבודה. השם מתאר דבר שנעשה עד הסוף.")
n("לבונה", "לבונה היא שרף ריחני שנוטף מגזע של עצים שגדלים בחצי האי ערב ובאפריקה, ומקטירים אותה כדי להפיץ ריח. השם בא מהשורש ל־ב־נ, כמו לבן, בגלל הצבע הבהיר של השרף. בתנ״ך הלבונה היא אחד מהבשמים של הקטורת, ובנגב עוברת דרך הבשמים העתיקה.")
n("ליהוא", "ליהוא מחבר את המילים לי והוא, ופירושו הוא שלי. השם נבנה בעברית החדשה, כמו שמות נוספים שמחברים את המילה לי עם מילה אחרת, כמו ליה והיא־לי. האות א בסוף מראה שהחלק השני הוא המילה הוא.")
n("מגן", "מגן הוא כלי שמחזיקים מול הגוף כדי להגן מפני מכה, ובהשאלה כל מי ששומר ומגן על אחרים. המילה באה מהשורש ג־נ־נ, שעניינו הגנה. בתורה ה׳ אומר לאברם שהוא מגן לו. מגן הוא גם שם של קיבוץ בנגב המערבי.")
n("מון", "מון היא המילה האנגלית לירח, הגוף שמאיר בשמיים בלילה ומשנה את הצורה שלו במשך החודש. בשפות רבות של אירופה המילה לירח קשורה גם למילה לחודש. כשם, מון מביא תמונה של אור רך בלילה.")
n("מחמד", "מחמד הוא כתיב אחר של מוחמד, השם הערבי שפירושו המהולל, ובא מהשורש ח־מ־ד, שעניינו שבח ותהילה. בערבית שני הכתיבים הם אותו שם. בעברית יש מילה שנכתבת כמו השם, מחמד, דבר יקר ואהוב, כמו בצירוף מחמד עיניים, אבל המשמעות שלה אחרת.", ["מוחמד"])
n("מילנה", "מילנה הוא שם סלאבי, שבנוי על המילה מיל, יקר ואהוב, ופירושו אהובה. השם מוכר בשפות סלאביות רבות, ובכל אחת הוא נשמע מעט אחרת. בעברית הוא נכתב גם מילאנה, באותה הגייה.", ["מילאנה"])
n("ניבי", "ניבי בנוי על המילה ניב, עם הסיומת ־י, ופירושו הדיבור שלי. ניב הוא דיבור ומבע, ובעברית של היום הוא גם דרך מיוחדת לדבר של קבוצה או של מקום, וגם ביטוי קבוע בשפה. מאותה מילה נבנה גם השם ניב.", ["ניב"])
n("סאדק", "סאדק בא מהשורש הערבי צ־ד־ק, שעניינו אמת וכנות, ופירושו מי שדובר אמת ונאמן לדבריו. השורש משותף לערבית ולעברית, ובעברית ממנו באות המילים צדק וצדיק. בערבית מאותו שורש באה גם המילה צדיק, חבר קרוב.")
n("סבאח", "סבאח היא המילה הערבית לבוקר, הזמן שבו השמש עולה ומתחיל יום חדש. בברכת הבוקר הערבית, צבאח אל־ח'יר, שמוכרת היטב גם בעברית המדוברת, מאחלים בוקר טוב. כשם, סבאח מביא תמונה של אור ראשון ושל התחלה.")
n("סובחי", "סובחי בנוי על המילה הערבית סובח, שחר, עם הסיומת ־י, שהופכת אותה לתואר, ופירושו של הבוקר, של השחר. מאותו שורש באה גם המילה סבאח, בוקר. כשם, סובחי מביא תמונה של הזמן שבו האור הראשון מופיע בשמיים.")

